/**
 * Single use. The row is marked used only while it is still unused and
 * unexpired, so two confirmations racing on one link cannot both succeed.
 * Returns `false` when the link was already consumed, retired or expired.
 */
export async function consumeResetToken(id: string): Promise<boolean> {
  const now = new Date().toISOString();
  const stamp = toIsoTimestamp(now);
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(
        eq(passwordResetTokens.id, id),
        gt(passwordResetTokens.expiresAt, now),
        isNull(passwordResetTokens.usedAt),
      ),
    )
    .returning({ id: passwordResetTokens.id })
    .all();
  return rows.length === 1;
}

