/** Buckets guarding the unauthenticated endpoints, each charged per account. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";
/** Confirmations are charged per link, not per account, so no one else's activity can block them. */
const RESET_CONFIRM_BUCKET = "auth:password-reset:confirm";

/**
 * Rate-limit key for one account. The address is lower-cased so letter case
 * cannot be used to dodge the limit, and every account has its own bucket, so
 * one account's failures never throttle another. The bucket is the same whether
 * or not the address has an account, so it reveals nothing about who exists.
 */
function accountBucket(bucket: string, address: string): string {
  return `${bucket}:${address.toLowerCase()}`;
}

/**
 * Rate limiting before a session exists has no tenant to charge against, so
 * the unauthenticated buckets are filed under this sentinel org. The account
 * is carried in the bucket key.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/**
 * How long a password-reset link stays usable after it is sent. A link is also
 * single use, and requesting a newer one retires the older ones.
 */
const RESET_TTL_MS = 60 * 60 * 1000;

