/**
 * Consumes a reset link, rewrites the password hash and ends every session of
 * the account. The link is consumed before the new hash is written, and the
 * consume is conditional, so a replayed or concurrent use of the same link
 * cannot overwrite a password the user has since changed again.
 */
export async function confirmPasswordReset(
  input: PasswordResetConfirmInput,
): Promise<User> {
  const tokenHash = hashToken(input.token);
  const verdict = await consumeRateLimit(
    ANONYMOUS_ORG,
    `${RESET_CONFIRM_BUCKET}:${tokenHash}`,
  );
  if (!verdict.allowed) {
    throw new Error("Too many reset attempts; try again shortly");
  }

  const stored = await resetTokenRepo.findLiveResetToken(tokenHash);
  if (!stored) throw new Error("That reset link is no longer valid");

  if (!(await resetTokenRepo.consumeResetToken(stored.id))) {
    throw new Error("That reset link is no longer valid");
  }
  await userRepo.updatePasswordHash(
    stored.userId,
    await hashPassword(input.password),
  );
  await sessionRepo.revokeUserSessions(stored.userId);

  const user = await userRepo.findUserById(stored.userId);

