/* Temporary scenario check for the sign-in / sign-out / reset fixes. Deleted after the run. */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { hashPassword } from "@/lib/hash";
import { resetRateLimits } from "@/lib/rate-limit";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import {
  confirmPasswordReset,
  login,
  requestPasswordReset,
} from "@/server/services/auth-service";
import {
  createSessionToken,
  destroySession,
  resolveSession,
} from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { resetTestDb, setupTestDb } from "./helpers/db";

const mail = vi.hoisted(() => ({
  render: vi.fn(
    async (_template: string, _props: Record<string, unknown>) => ({
      subject: "s",
      html: "<p>h</p>",
    }),
  ),
  send: vi.fn(async (_message: unknown) => undefined),
}));

vi.mock("@/server/services/email-service", () => ({
  renderEmail: mail.render,
  sendEmail: mail.send,
}));

const BASE = new Date("2026-03-15T12:00:00.000Z");
const MINUTE = 60 * 1000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;
const OLD_PASSWORD = "Old-password-123";
const NEW_PASSWORD = "New-password-456";

function setNow(ms: number): void {
  vi.setSystemTime(new Date(BASE.getTime() + ms));
}

async function makeUser(email: string) {
  return userRepo.insertUser({
    email,
    name: email.split("@")[0] ?? "user",
    passwordHash: await hashPassword(OLD_PASSWORD),
  });
}

function resetTokens(): string[] {
  return mail.render.mock.calls
    .filter(([template]) => template === "password-reset")
    .map(([, props]) => props.token as string);
}

function lastResetToken(): string {
  const tokens = resetTokens();
  const token = tokens.at(-1);
  if (!token) throw new Error("no reset token was sent");
  return token;
}

async function expiresInMs(token: string): Promise<number> {
  const principal = await resolveSession(token);
  if (!principal) throw new Error("session not resolvable");
  return Date.parse(principal.expiresAt) - BASE.getTime();
}

beforeEach(async () => {
  await resetTestDb();
  resetRateLimits();
  mail.render.mockClear();
  mail.send.mockClear();
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(BASE);
});

afterEach(() => {
  vi.useRealTimers();
});

describe("sign-out", () => {
  it("ends only the session that signed out", async () => {
    const alice = await makeUser("alice@example.test");
    const bob = await makeUser("bob@example.test");
    const aliceLaptop = await createSessionToken(alice.id);
    const alicePhone = await createSessionToken(alice.id);
    const bobLaptop = await createSessionToken(bob.id);

    await destroySession(aliceLaptop.token);

    expect(await resolveSession(aliceLaptop.token)).toBeNull();
    expect(await resolveSession(alicePhone.token)).not.toBeNull();
    expect(await resolveSession(bobLaptop.token)).not.toBeNull();
  });

  it("treats an unknown or already-ended session as a no-op, and sign-in afterwards works", async () => {
    const alice = await makeUser("alice@example.test");
    const other = await createSessionToken(alice.id);

    await expect(
      destroySession("unknown-token-value-aaaaaaaaaaaaaaaaaaaaaaaa"),
    ).resolves.toBeUndefined();
    const own = await createSessionToken(alice.id);
    await destroySession(own.token);
    await expect(destroySession(own.token)).resolves.toBeUndefined();

    expect(await resolveSession(other.token)).not.toBeNull();
    const fresh = await login({
      email: "alice@example.test",
      password: OLD_PASSWORD,
      rememberMe: false,
    });
    expect(await resolveSession(fresh.token)).not.toBeNull();
  });
});

describe("session lifetime and remember me", () => {
  it("lasts 24 hours without remember me and 30 days with it", async () => {
    const alice = await makeUser("alice@example.test");
    const plain = await createSessionToken(alice.id);
    const remembered = await createSessionToken(alice.id, { rememberMe: true });

    expect(await expiresInMs(plain.token)).toBe(DAY);
    expect(await expiresInMs(remembered.token)).toBe(30 * DAY);
  });

  it("is refused past its lifetime", async () => {
    const alice = await makeUser("alice@example.test");
    const plain = await createSessionToken(alice.id);
    const remembered = await createSessionToken(alice.id, { rememberMe: true });

    setNow(25 * HOUR);
    expect(await resolveSession(plain.token)).toBeNull();
    expect(await resolveSession(remembered.token)).not.toBeNull();

    setNow(31 * DAY);
    expect(await resolveSession(remembered.token)).toBeNull();
  });

  it("login passes remember me through to the session", async () => {
    await makeUser("alice@example.test");
    const plain = await login({
      email: "alice@example.test",
      password: OLD_PASSWORD,
      rememberMe: false,
    });
    const remembered = await login({
      email: "alice@example.test",
      password: OLD_PASSWORD,
      rememberMe: true,
    });

    expect(await expiresInMs(plain.token)).toBe(DAY);
    expect(await expiresInMs(remembered.token)).toBe(30 * DAY);
  });

  it("purges only expired sessions", async () => {
    const alice = await makeUser("alice@example.test");
    const shortLived = await createSessionToken(alice.id);
    const longLived = await createSessionToken(alice.id, { rememberMe: true });

    setNow(25 * HOUR);
    const removed = await sessionRepo.purgeExpiredSessions(
      toIsoTimestamp(new Date()),
    );

    expect(removed).toBe(1);
    expect(await resolveSession(longLived.token)).not.toBeNull();
    expect(await resolveSession(shortLived.token)).toBeNull();
  });
});

describe("password reset", () => {
  it("a link works once", async () => {
    await makeUser("alice@example.test");
    await requestPasswordReset({ email: "alice@example.test" });
    const token = lastResetToken();

    await expect(
      confirmPasswordReset({ token, password: NEW_PASSWORD }),
    ).resolves.toBeDefined();
    await expect(
      confirmPasswordReset({ token, password: "Another-password-789" }),
    ).rejects.toThrow("no longer valid");
  });

  it("is usable for 60 minutes after it is sent and no longer", async () => {
    await makeUser("alice@example.test");
    await requestPasswordReset({ email: "alice@example.test" });
    const early = lastResetToken();
    setNow(59 * MINUTE);
    await expect(
      confirmPasswordReset({ token: early, password: NEW_PASSWORD }),
    ).resolves.toBeDefined();

    await requestPasswordReset({ email: "alice@example.test" });
    const late = lastResetToken();
    setNow(59 * MINUTE + 61 * MINUTE);
    await expect(
      confirmPasswordReset({ token: late, password: NEW_PASSWORD }),
    ).rejects.toThrow("no longer valid");
  });

  it("a newer request retires earlier links of that account only", async () => {
    await makeUser("alice@example.test");
    const bob = await makeUser("bob@example.test");
    await requestPasswordReset({ email: "alice@example.test" });
    const aliceFirst = lastResetToken();
    await requestPasswordReset({ email: "bob@example.test" });
    const bobLink = lastResetToken();
    await requestPasswordReset({ email: "alice@example.test" });
    const aliceSecond = lastResetToken();

    await expect(
      confirmPasswordReset({ token: aliceFirst, password: NEW_PASSWORD }),
    ).rejects.toThrow("no longer valid");
    await expect(
      confirmPasswordReset({ token: bobLink, password: NEW_PASSWORD }),
    ).resolves.toMatchObject({ id: bob.id });
    await expect(
      confirmPasswordReset({ token: aliceSecond, password: NEW_PASSWORD }),
    ).resolves.toBeDefined();
  });

  it("ends every session of that account and no one else's, and the new password replaces the old", async () => {
    const alice = await makeUser("alice@example.test");
    const bob = await makeUser("bob@example.test");
    const aliceLaptop = await createSessionToken(alice.id);
    const aliceOther = await createSessionToken(alice.id, { rememberMe: true });
    const bobLaptop = await createSessionToken(bob.id);

    await requestPasswordReset({ email: "alice@example.test" });
    await confirmPasswordReset({
      token: lastResetToken(),
      password: NEW_PASSWORD,
    });

    expect(await resolveSession(aliceLaptop.token)).toBeNull();
    expect(await resolveSession(aliceOther.token)).toBeNull();
    expect(await resolveSession(bobLaptop.token)).not.toBeNull();

    const signedIn = await login({
      email: "alice@example.test",
      password: NEW_PASSWORD,
      rememberMe: false,
    });
    expect(await resolveSession(signedIn.token)).not.toBeNull();
    await expect(
      login({
        email: "alice@example.test",
        password: OLD_PASSWORD,
        rememberMe: false,
      }),
    ).rejects.toThrow("Those credentials did not match");
  });

  it("completes silently for an unknown address, with no link sent", async () => {
    await expect(
      requestPasswordReset({ email: "nobody@example.test" }),
    ).resolves.toBeUndefined();
    expect(mail.send).not.toHaveBeenCalled();
  });

  it("matches addresses without regard to letter case", async () => {
    await makeUser("alice@example.test");
    await requestPasswordReset({ email: "ALICE@Example.test" });
    expect(mail.send).toHaveBeenCalledTimes(1);
  });
});

describe("throttling", () => {
  it("one account's failed sign-ins never lock another account out", async () => {
    await makeUser("alice@example.test");
    await makeUser("bob@example.test");

    let refused = false;
    for (let i = 0; i < 100 && !refused; i += 1) {
      await login({
        email: "alice@example.test",
        password: "Wrong-password-000",
        rememberMe: false,
      }).catch((error: Error) => {
        if (error.message.includes("Too many")) refused = true;
      });
    }
    expect(refused).toBe(true);

    await expect(
      login({ email: "alice@example.test", password: OLD_PASSWORD, rememberMe: false }),
    ).rejects.toThrow("Too many sign-in attempts");
    await expect(
      login({ email: "ALICE@example.test", password: OLD_PASSWORD, rememberMe: false }),
    ).rejects.toThrow("Too many sign-in attempts");
    await expect(
      login({ email: "bob@example.test", password: OLD_PASSWORD, rememberMe: false }),
    ).resolves.toBeDefined();
  });

  it("a throttled account is refused with the right password, can still reset, and recovers over time", async () => {
    await makeUser("alice@example.test");
    let refused = false;
    for (let i = 0; i < 100 && !refused; i += 1) {
      await login({
        email: "alice@example.test",
        password: "Wrong-password-000",
        rememberMe: false,
      }).catch((error: Error) => {
        if (error.message.includes("Too many")) refused = true;
      });
    }

    await expect(
      login({ email: "alice@example.test", password: OLD_PASSWORD, rememberMe: false }),
    ).rejects.toThrow("Too many sign-in attempts");

    await requestPasswordReset({ email: "alice@example.test" });
    expect(mail.send).toHaveBeenCalledTimes(1);
    await expect(
      confirmPasswordReset({ token: lastResetToken(), password: NEW_PASSWORD }),
    ).resolves.toBeDefined();

    setNow(2 * MINUTE);
    await expect(
      login({ email: "alice@example.test", password: NEW_PASSWORD, rememberMe: false }),
    ).resolves.toBeDefined();
  });

  it("reset requests are limited per address, independently of other addresses", async () => {
    await makeUser("alice@example.test");
    await makeUser("bob@example.test");
    for (let i = 0; i < 10; i += 1) {
      await requestPasswordReset({ email: "alice@example.test" });
    }
    expect(mail.send).toHaveBeenCalledTimes(5);

    await requestPasswordReset({ email: "bob@example.test" });
    expect(mail.send).toHaveBeenCalledTimes(6);
  });

  it("reset confirmations are not blocked by someone else's failed attempts", async () => {
    await makeUser("alice@example.test");
    await requestPasswordReset({ email: "alice@example.test" });
    const real = lastResetToken();
    for (let i = 0; i < 10; i += 1) {
      await confirmPasswordReset({
        token: "not-a-real-token-value-0000",
        password: NEW_PASSWORD,
      }).catch(() => undefined);
    }
    await expect(
      confirmPasswordReset({ token: real, password: NEW_PASSWORD }),
    ).resolves.toBeDefined();
  });
});

